package ae.png;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.zip.CRC32;
import java.util.zip.Deflater;

/** Writes non-interlaced PNG files: IHDR, [PLTE], one IDAT, IEND. */
public final class PngEncoder {
    static final byte[] SIGNATURE = {(byte) 0x89, 'P', 'N', 'G', 13, 10, 26, 10};

    private PngEncoder() {}

    public static byte[] encode(Png png, FilterMode mode) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.writeBytes(SIGNATURE);
        byte[] ihdr = new byte[13];
        putInt(ihdr, 0, png.width());
        putInt(ihdr, 4, png.height());
        ihdr[8] = (byte) png.bitDepth();
        ihdr[9] = (byte) png.colorType();
        writeChunk(out, "IHDR", ihdr);
        if (png.colorType() == 3) {
            int[] pal = png.palette();
            byte[] plte = new byte[pal.length * 3];
            for (int i = 0; i < pal.length; i++) {
                plte[3 * i] = (byte) (pal[i] >> 16);
                plte[3 * i + 1] = (byte) (pal[i] >> 8);
                plte[3 * i + 2] = (byte) pal[i];
            }
            writeChunk(out, "PLTE", plte);
        }
        writeChunk(out, "IDAT", deflate(filteredScanlines(png, mode)));
        writeChunk(out, "IEND", new byte[0]);
        return out.toByteArray();
    }

    /** Scanlines as stored before compression: each row is a filter-type byte plus the filtered packed row. */
    static byte[] filteredScanlines(Png png, FilterMode mode) {
        int rb = png.rowBytes();
        int bpp = png.bpp();
        byte[] result = new byte[png.height() * (rb + 1)];
        byte[] prior = new byte[rb];
        for (int y = 0; y < png.height(); y++) {
            byte[] row = pack(png, y);
            int bestType;
            byte[] best;
            if (mode == FilterMode.ADAPTIVE) {
                bestType = 0;
                best = PngFilter.filter(0, row, prior, bpp);
                long bestScore = score(best);
                for (int t = 1; t <= 4; t++) {
                    byte[] cand = PngFilter.filter(t, row, prior, bpp);
                    long sc = score(cand);
                    if (sc < bestScore) { // strict: ties keep the lowest type
                        bestScore = sc;
                        bestType = t;
                        best = cand;
                    }
                }
            } else {
                bestType = mode.ordinal();
                best = PngFilter.filter(bestType, row, prior, bpp);
            }
            int off = y * (rb + 1);
            result[off] = (byte) bestType;
            System.arraycopy(best, 0, result, off + 1, rb);
            prior = row;
        }
        return result;
    }

    private static long score(byte[] filtered) {
        long s = 0;
        for (byte b : filtered) s += Math.abs((int) b);
        return s;
    }

    /** Packs row {@code y} of samples at the image's bit depth, MSB first, padding the last byte with zeros. */
    private static byte[] pack(Png png, int y) {
        int perRow = png.width() * Png.channels(png.colorType());
        int depth = png.bitDepth();
        byte[] row = new byte[png.rowBytes()];
        int[] s = png.samples();
        for (int i = 0; i < perRow; i++) {
            int v = s[y * perRow + i];
            if (depth == 8) {
                row[i] = (byte) v;
            } else {
                int bit = i * depth;
                row[bit >> 3] |= (byte) (v << (8 - depth - (bit & 7)));
            }
        }
        return row;
    }

    private static byte[] deflate(byte[] data) {
        Deflater d = new Deflater(9);
        try {
            d.setInput(data);
            d.finish();
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            while (!d.finished()) out.write(buf, 0, d.deflate(buf));
            return out.toByteArray();
        } finally {
            d.end();
        }
    }

    static void writeChunk(ByteArrayOutputStream out, String type, byte[] data) {
        byte[] t = type.getBytes(StandardCharsets.US_ASCII);
        byte[] len = new byte[4];
        putInt(len, 0, data.length);
        out.writeBytes(len);
        out.writeBytes(t);
        out.writeBytes(data);
        CRC32 crc = new CRC32();
        crc.update(t);
        crc.update(data);
        byte[] c = new byte[4];
        putInt(c, 0, (int) crc.getValue());
        out.writeBytes(c);
    }

    static void putInt(byte[] b, int off, int v) {
        b[off] = (byte) (v >>> 24);
        b[off + 1] = (byte) (v >>> 16);
        b[off + 2] = (byte) (v >>> 8);
        b[off + 3] = (byte) v;
    }
}

package ae.png;

/** The five PNG scanline filters (None, Sub, Up, Average, Paeth) on unpacked byte rows. */
public final class PngFilter {
    private PngFilter() {}

    /** The Paeth predictor; ties break in the order a, b, c. */
    static int paeth(int a, int b, int c) {
        int p = a + b - c;
        int pa = Math.abs(p - a);
        int pb = Math.abs(p - b);
        int pc = Math.abs(p - c);
        if (pa <= pb && pa <= pc) return a;
        if (pb <= pc) return b;
        return c;
    }

    private static void checkType(int type) {
        if (type < 0 || type > 4) throw new IllegalArgumentException("bad filter type " + type);
    }

    /** Predictor value for byte {@code i} given the already reconstructed row {@code cur}. */
    private static int predict(int type, byte[] cur, byte[] prior, int bpp, int i) {
        int a = i >= bpp ? cur[i - bpp] & 0xFF : 0;
        int b = prior[i] & 0xFF;
        int c = i >= bpp ? prior[i - bpp] & 0xFF : 0;
        return switch (type) {
            case 0 -> 0;
            case 1 -> a;
            case 2 -> b;
            case 3 -> (a + b) / 2;
            default -> paeth(a, b, c);
        };
    }

    /** Filters {@code row}; {@code prior} is the previous raw row (all zero for the first row). */
    public static byte[] filter(int type, byte[] row, byte[] prior, int bpp) {
        checkType(type);
        byte[] out = new byte[row.length];
        for (int i = 0; i < row.length; i++) {
            out[i] = (byte) (row[i] - predict(type, row, prior, bpp, i));
        }
        return out;
    }

    /** Reverses {@link #filter}: {@code prior} is the previous reconstructed row. */
    public static byte[] unfilter(int type, byte[] filtered, byte[] prior, int bpp) {
        checkType(type);
        byte[] out = new byte[filtered.length];
        for (int i = 0; i < filtered.length; i++) {
            out[i] = (byte) (filtered[i] + predict(type, out, prior, bpp, i));
        }
        return out;
    }
}

package ae.png;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.zip.CRC32;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;

/** Strict decoder for non-interlaced PNG files. All defects raise IllegalArgumentException with a descriptive message. */
public final class PngDecoder {
    private PngDecoder() {}

    private static IllegalArgumentException bad(String msg) {
        return new IllegalArgumentException(msg);
    }

    private static int getInt(byte[] b, int off) {
        return ((b[off] & 0xFF) << 24) | ((b[off + 1] & 0xFF) << 16) | ((b[off + 2] & 0xFF) << 8) | (b[off + 3] & 0xFF);
    }

    public static Png decode(byte[] data) {
        if (data.length < 8 || !Arrays.equals(Arrays.copyOf(data, 8), PngEncoder.SIGNATURE)) {
            throw bad("bad signature");
        }
        int pos = 8;
        int width = 0, height = 0, depth = 0, colorType = 0;
        int[] palette = null;
        boolean sawIhdr = false, sawIdat = false, idatClosed = false, sawIend = false;
        ByteArrayOutputStream idat = new ByteArrayOutputStream();
        int chunkNo = 0;
        while (!sawIend) {
            if (data.length - pos < 12) throw bad("truncated chunk header");
            long len = getInt(data, pos) & 0xFFFFFFFFL;
            if (len > data.length - pos - 12) throw bad("truncated chunk (length " + len + ")");
            String type = new String(data, pos + 4, 4, StandardCharsets.ISO_8859_1);
            for (int i = 0; i < 4; i++) {
                char ch = type.charAt(i);
                if (!(ch >= 'A' && ch <= 'Z') && !(ch >= 'a' && ch <= 'z')) throw bad("bad chunk type");
            }
            int dataStart = pos + 8;
            int n = (int) len;
            CRC32 crc = new CRC32();
            crc.update(data, pos + 4, 4 + n);
            if ((int) crc.getValue() != getInt(data, dataStart + n)) throw bad("bad CRC in " + type);
            if (chunkNo == 0 && !type.equals("IHDR")) throw bad("IHDR must be the first chunk");
            chunkNo++;
            if (type.equals("IDAT")) {
                if (!sawIhdr) throw bad("IDAT before IHDR");
                if (idatClosed) throw bad("non-contiguous IDAT");
                sawIdat = true;
                idat.write(data, dataStart, n);
            } else {
                if (sawIdat) idatClosed = true;
                switch (type) {
                    case "IHDR" -> {
                        if (sawIhdr) throw bad("duplicate IHDR");
                        if (n != 13) throw bad("IHDR length " + n);
                        sawIhdr = true;
                        long w = getInt(data, dataStart) & 0xFFFFFFFFL;
                        long h = getInt(data, dataStart + 4) & 0xFFFFFFFFL;
                        depth = data[dataStart + 8] & 0xFF;
                        colorType = data[dataStart + 9] & 0xFF;
                        if (w < 1 || h < 1 || w > Png.MAX_DIM || h > Png.MAX_DIM || w * h > Png.MAX_PIXELS) {
                            throw bad("bad dimensions " + w + "x" + h);
                        }
                        width = (int) w;
                        height = (int) h;
                        if (!Png.validDepth(colorType, depth)) throw bad("illegal colour type/bit depth " + colorType + "/" + depth);
                        if (data[dataStart + 10] != 0) throw bad("unknown compression method");
                        if (data[dataStart + 11] != 0) throw bad("unknown filter method");
                        if (data[dataStart + 12] == 1) throw bad("interlace is not supported");
                        if (data[dataStart + 12] != 0) throw bad("unknown interlace method");
                    }
                    case "PLTE" -> {
                        if (palette != null) throw bad("duplicate PLTE");
                        if (sawIdat) throw bad("PLTE after IDAT");
                        if (colorType == 0 || colorType == 4) throw bad("PLTE not allowed for colour type " + colorType);
                        if (n % 3 != 0 || n == 0) throw bad("PLTE length " + n + " not a positive multiple of 3");
                        if (n / 3 > (1 << depth) && colorType == 3) throw bad("PLTE has too many entries");
                        if (n / 3 > 256) throw bad("PLTE has too many entries");
                        palette = new int[n / 3];
                        for (int i = 0; i < palette.length; i++) {
                            palette[i] = ((data[dataStart + 3 * i] & 0xFF) << 16)
                                    | ((data[dataStart + 3 * i + 1] & 0xFF) << 8)
                                    | (data[dataStart + 3 * i + 2] & 0xFF);
                        }
                    }
                    case "IEND" -> {
                        if (n != 0) throw bad("IEND must be empty");
                        sawIend = true;
                    }
                    default -> {
                        if (Character.isUpperCase(type.charAt(0))) throw bad("unknown critical chunk " + type);
                    }
                }
            }
            pos = dataStart + n + 4;
        }
        if (pos != data.length) throw bad("data after IEND");
        if (!sawIdat) throw bad("missing IDAT");
        if (colorType == 3 && palette == null) throw bad("missing PLTE");
        if (colorType != 3) palette = null; // a (legal) suggested palette on truecolour images is ignored

        int rb = (int) (((long) width * Png.channels(colorType) * depth + 7) / 8);
        int bpp = Math.max(1, Png.channels(colorType) * depth / 8);
        byte[] raw = inflate(idat.toByteArray(), (long) height * (rb + 1));

        int perRow = width * Png.channels(colorType);
        int[] samples = new int[height * perRow];
        byte[] prior = new byte[rb];
        for (int y = 0; y < height; y++) {
            int off = y * (rb + 1);
            int ft = raw[off] & 0xFF;
            if (ft > 4) throw bad("bad filter type byte " + ft + " in row " + y);
            byte[] row = PngFilter.unfilter(ft, Arrays.copyOfRange(raw, off + 1, off + 1 + rb), prior, bpp);
            for (int i = 0; i < perRow; i++) {
                int v;
                if (depth == 8) {
                    v = row[i] & 0xFF;
                } else {
                    int bit = i * depth;
                    v = ((row[bit >> 3] & 0xFF) >> (8 - depth - (bit & 7))) & ((1 << depth) - 1);
                }
                samples[y * perRow + i] = v;
            }
            prior = row;
        }
        if (colorType == 3) {
            for (int s : samples) if (s >= palette.length) throw bad("palette index " + s + " out of range");
        }
        return new Png(width, height, colorType, depth, samples, palette);
    }

    /** Inflates exactly {@code expected} bytes; fewer or more is an error. */
    private static byte[] inflate(byte[] z, long expected) {
        Inflater inf = new Inflater();
        try {
            inf.setInput(z);
            byte[] out = new byte[(int) expected];
            int got = 0;
            while (got < out.length) {
                int k = inf.inflate(out, got, out.length - got);
                if (k == 0 && (inf.finished() || inf.needsInput() || inf.needsDictionary())) {
                    throw bad("image data too short: " + got + " of " + expected + " bytes");
                }
                got += k;
            }
            byte[] probe = new byte[1];
            if (inf.inflate(probe) != 0 || !inf.finished()) {
                throw bad("image data too long or stream not terminated");
            }
            if (inf.getRemaining() != 0) throw bad("trailing bytes after zlib stream");
            return out;
        } catch (DataFormatException e) {
            throw bad("corrupt zlib stream: " + e.getMessage());
        } finally {
            inf.end();
        }
    }
}

package ae.png;

/** How the encoder chooses the scanline filter: a fixed type for every row, or per-row adaptive. */
public enum FilterMode {
    FIXED_0, FIXED_1, FIXED_2, FIXED_3, FIXED_4, ADAPTIVE
}

package ae.png;

import java.util.Arrays;

/**
 * A decoded PNG: one int per sample, row-major, channels interleaved, top row first.
 * Sample index = (y*width + x)*channels + c. Palette entries are 0xRRGGBB.
 */
public record Png(int width, int height, int colorType, int bitDepth, int[] samples, int[] palette) {
    public static final int MAX_DIM = 16384;
    public static final long MAX_PIXELS = 4_000_000L;

    public Png {
        if (!validDepth(colorType, bitDepth)) {
            throw new IllegalArgumentException("illegal colour type/bit depth " + colorType + "/" + bitDepth);
        }
        if (width < 1 || height < 1 || width > MAX_DIM || height > MAX_DIM || (long) width * height > MAX_PIXELS) {
            throw new IllegalArgumentException("bad dimensions " + width + "x" + height);
        }
        if (samples.length != width * height * channels(colorType)) {
            throw new IllegalArgumentException("sample count mismatch");
        }
        int max = (1 << bitDepth) - 1;
        if (colorType == 3) {
            if (palette == null || palette.length < 1 || palette.length > (1 << bitDepth)) {
                throw new IllegalArgumentException("bad palette size");
            }
            for (int rgb : palette) {
                if ((rgb >>> 24) != 0) throw new IllegalArgumentException("palette entry not 0xRRGGBB");
            }
            for (int s : samples) {
                if (s < 0 || s >= palette.length) throw new IllegalArgumentException("palette index out of range: " + s);
            }
            palette = palette.clone();
        } else {
            if (palette != null) throw new IllegalArgumentException("palette only for colour type 3");
            for (int s : samples) {
                if (s < 0 || s > max) throw new IllegalArgumentException("sample out of range: " + s);
            }
        }
        samples = samples.clone();
    }

    public static boolean validDepth(int colorType, int depth) {
        return switch (colorType) {
            case 0, 3 -> depth == 1 || depth == 2 || depth == 4 || depth == 8;
            case 2, 4, 6 -> depth == 8;
            default -> false;
        };
    }

    public static int channels(int colorType) {
        return switch (colorType) {
            case 0, 3 -> 1;
            case 2 -> 3;
            case 4 -> 2;
            case 6 -> 4;
            default -> throw new IllegalArgumentException("bad colour type " + colorType);
        };
    }

    /** Bytes in one packed scanline (without the filter byte). */
    public int rowBytes() {
        return (int) (((long) width * channels(colorType) * bitDepth + 7) / 8);
    }

    /** Filter distance: bytes per complete pixel, at least 1. */
    public int bpp() {
        return Math.max(1, channels(colorType) * bitDepth / 8);
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof Png p && width == p.width && height == p.height && colorType == p.colorType
                && bitDepth == p.bitDepth && Arrays.equals(samples, p.samples) && Arrays.equals(palette, p.palette);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(samples) * 31 + Arrays.hashCode(palette) + width * 7 + height * 13 + colorType + bitDepth;
    }

    @Override
    public String toString() {
        return "Png[" + width + "x" + height + " type=" + colorType + " depth=" + bitDepth + "]";
    }
}

