package ae.png;

import static org.junit.jupiter.api.Assertions.*;

import java.util.Random;
import org.junit.jupiter.api.Test;

class PngFilterTest {
    private static final byte[] ROW = {10, 20, 30, 40};
    private static final byte[] PRIOR = {1, 2, 3, 4};
    private static final byte[] ZERO = new byte[4];

    @Test
    void noneIsIdentity() {
        assertArrayEquals(ROW, PngFilter.filter(0, ROW, PRIOR, 1));
    }

    @Test
    void subLiteral() {
        // x0: 10-0, x1: 20-10, x2: 30-20, x3: 40-30
        assertArrayEquals(new byte[] {10, 10, 10, 10}, PngFilter.filter(1, ROW, PRIOR, 1));
    }

    @Test
    void subUsesBytesPerPixelDistance() {
        // bpp 2: x2 - x0 = 30-10, x3 - x1 = 40-20
        assertArrayEquals(new byte[] {10, 20, 20, 20}, PngFilter.filter(1, ROW, PRIOR, 2));
    }

    @Test
    void upLiteral() {
        assertArrayEquals(new byte[] {9, 18, 27, 36}, PngFilter.filter(2, ROW, PRIOR, 1));
    }

    @Test
    void averageLiteral() {
        // x0: 10-floor((0+1)/2)=10; x1: 20-floor((10+2)/2)=14; x2: 30-floor((20+3)/2)=19; x3: 40-floor((30+4)/2)=23
        assertArrayEquals(new byte[] {10, 14, 19, 23}, PngFilter.filter(3, ROW, PRIOR, 1));
    }

    @Test
    void paethLiteral() {
        // x0 predictor b=1 -> 9; x1 a=10 -> 10; x2 a=20 -> 10; x3 a=30 -> 10
        assertArrayEquals(new byte[] {9, 10, 10, 10}, PngFilter.filter(4, ROW, PRIOR, 1));
    }

    @Test
    void paethPredictorTieBreakOrderIsAThenBThenC() {
        assertEquals(3, PngFilter.paeth(3, 0, 1)); // pa=1 pb=2 pc=1 -> a wins the pa==pc tie
        assertEquals(3, PngFilter.paeth(0, 3, 1)); // pa=2 pb=1 pc=1 -> b wins the pb==pc tie
        assertEquals(3, PngFilter.paeth(2, 4, 3)); // pa=1 pb=1 pc=0 -> c
        assertEquals(7, PngFilter.paeth(7, 7, 7));
        assertEquals(0, PngFilter.paeth(0, 0, 0));
    }

    @Test
    void paethHandlesFullByteRange() {
        assertEquals(0, PngFilter.paeth(255, 0, 255)); // p=0: pa=255 pb=0 pc=255 -> b
    }

    @Test
    void firstRowUsesZeroPrior() {
        assertArrayEquals(new byte[] {10, 20, 30, 40}, PngFilter.filter(2, ROW, ZERO, 1));
    }

    @Test
    void wrapsModulo256() {
        byte[] row = {(byte) 5};
        byte[] prior = {(byte) 250};
        assertArrayEquals(new byte[] {(byte) 11}, PngFilter.filter(2, row, prior, 1)); // 5-250 = -245 = 11 mod 256
        assertArrayEquals(row, PngFilter.unfilter(2, new byte[] {11}, prior, 1));
    }

    @Test
    void unfilterInvertsFilterForAllTypesAndBpps() {
        Random rnd = new Random(7);
        for (int iter = 0; iter < 300; iter++) {
            int bpp = 1 + rnd.nextInt(4);
            int len = bpp * (1 + rnd.nextInt(8));
            byte[] row = new byte[len];
            byte[] prior = new byte[len];
            rnd.nextBytes(row);
            if (rnd.nextBoolean()) rnd.nextBytes(prior);
            for (int t = 0; t <= 4; t++) {
                byte[] f = PngFilter.filter(t, row, prior, bpp);
                assertArrayEquals(row, PngFilter.unfilter(t, f, prior, bpp), "type " + t + " bpp " + bpp);
            }
        }
    }

    @Test
    void filtersDoNotMutateInputs() {
        byte[] row = ROW.clone();
        byte[] prior = PRIOR.clone();
        for (int t = 0; t <= 4; t++) {
            PngFilter.filter(t, row, prior, 1);
            PngFilter.unfilter(t, row, prior, 1);
        }
        assertArrayEquals(ROW, row);
        assertArrayEquals(PRIOR, prior);
    }

    @Test
    void rejectsBadFilterType() {
        assertThrows(IllegalArgumentException.class, () -> PngFilter.filter(5, ROW, PRIOR, 1));
        assertThrows(IllegalArgumentException.class, () -> PngFilter.unfilter(-1, ROW, PRIOR, 1));
    }
}

package ae.png;

import static org.junit.jupiter.api.Assertions.*;

import java.io.ByteArrayOutputStream;
import java.util.Random;
import java.util.zip.Deflater;
import org.junit.jupiter.api.Test;

/** Every image here is hand-assembled with VALID CRCs, so only the named structural defect can cause rejection. */
class PngCorruptionTest {
    static byte[] ihdr(int w, int h, int depth, int type, int comp, int filt, int interlace) {
        byte[] b = new byte[13];
        PngEncoder.putInt(b, 0, w);
        PngEncoder.putInt(b, 4, h);
        b[8] = (byte) depth;
        b[9] = (byte) type;
        b[10] = (byte) comp;
        b[11] = (byte) filt;
        b[12] = (byte) interlace;
        return b;
    }

    static byte[] z(byte[] raw) {
        Deflater d = new Deflater();
        d.setInput(raw);
        d.finish();
        byte[] buf = new byte[1024];
        int n = d.deflate(buf);
        d.end();
        return java.util.Arrays.copyOf(buf, n);
    }

    /** Builds a PNG from (type, data) pairs. */
    static byte[] build(Object... chunks) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        out.writeBytes(PngEncoder.SIGNATURE);
        for (int i = 0; i < chunks.length; i += 2) PngEncoder.writeChunk(out, (String) chunks[i], (byte[]) chunks[i + 1]);
        return out.toByteArray();
    }

    static final byte[] END = new byte[0];
    // 2x2 gray 8-bit, filter 0 on both rows: rows (1,2) and (3,4)
    static final byte[] RAW = {0, 1, 2, 0, 3, 4};

    static byte[] control() {
        return build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END);
    }

    static void rejects(byte[] png, String fragment) {
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> PngDecoder.decode(png));
        assertTrue(e.getMessage().contains(fragment), "message '" + e.getMessage() + "' lacks '" + fragment + "'");
    }

    @Test
    void controlDecodesToLiteralPixels() {
        Png p = PngDecoder.decode(control());
        assertArrayEquals(new int[] {1, 2, 3, 4}, p.samples());
        assertEquals(2, p.width());
    }

    @Test
    void badSignature() {
        byte[] b = control();
        b[1] = 'X';
        rejects(b, "signature");
        rejects(new byte[3], "signature");
    }

    @Test
    void badCrcAndTruncation() {
        byte[] b = control();
        b[b.length - 1] ^= 1; // IEND crc
        rejects(b, "CRC");
        byte[] c = control();
        rejects(java.util.Arrays.copyOf(c, c.length - 3), "truncated");
    }

    @Test
    void ihdrMustBeFirstAndUnique() {
        rejects(build("IDAT", z(RAW), "IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IEND", END), "IHDR must be the first");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "duplicate IHDR");
        rejects(build("IHDR", new byte[12], "IDAT", z(RAW), "IEND", END), "IHDR length");
    }

    @Test
    void illegalColourDepthPairsAndMethods() {
        rejects(build("IHDR", ihdr(2, 2, 16, 2, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "colour type/bit depth");
        rejects(build("IHDR", ihdr(2, 2, 4, 6, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "colour type/bit depth");
        rejects(build("IHDR", ihdr(2, 2, 8, 1, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "colour type/bit depth");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 1, 0, 0), "IDAT", z(RAW), "IEND", END), "compression");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 1, 0), "IDAT", z(RAW), "IEND", END), "filter method");
    }

    @Test
    void interlaceIsRejectedWithItsOwnMessage() {
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 1), "IDAT", z(RAW), "IEND", END), "interlace is not supported");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 2), "IDAT", z(RAW), "IEND", END), "unknown interlace");
    }

    @Test
    void dimensionsAreCappedBeforeAllocation() {
        rejects(build("IHDR", ihdr(0, 2, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "dimensions");
        rejects(build("IHDR", ihdr(16385, 1, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "dimensions");
        // 16384 x 16384 = 268M pixels would need a 268MB inflate buffer; must be refused up front
        rejects(build("IHDR", ihdr(16384, 16384, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "dimensions");
        rejects(build("IHDR", ihdr(-1, 2, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "dimensions"); // 0xFFFFFFFF
        // control just under the cap: 2000x2000 = 4,000,000 pixels is allowed by the cap (fails later only on data length)
        rejects(build("IHDR", ihdr(2000, 2000, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", END), "too short");
    }

    // palette 2x2, depth 8, indexes 0,1 / 1,0
    static final byte[] PRAW = {0, 0, 1, 0, 1, 0};
    static final byte[] PLTE2 = {1, 2, 3, 4, 5, 6};

    @Test
    void paletteControlAndDefects() {
        Png ok = PngDecoder.decode(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "PLTE", PLTE2, "IDAT", z(PRAW), "IEND", END));
        assertArrayEquals(new int[] {0x010203, 0x040506}, ok.palette());
        rejects(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "IDAT", z(PRAW), "IEND", END), "missing PLTE");
        rejects(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "PLTE", PLTE2, "PLTE", PLTE2, "IDAT", z(PRAW), "IEND", END), "duplicate PLTE");
        rejects(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "IDAT", z(PRAW), "PLTE", PLTE2, "IEND", END), "PLTE after IDAT");
        rejects(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "PLTE", new byte[] {1, 2, 3, 4}, "IDAT", z(PRAW), "IEND", END), "multiple of 3");
        rejects(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "PLTE", new byte[0], "IDAT", z(PRAW), "IEND", END), "multiple of 3");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "PLTE", PLTE2, "IDAT", z(RAW), "IEND", END), "not allowed");
    }

    @Test
    void paletteSizeIsBoundedByBitDepth() {
        // depth 1 allows 2 entries; 3 entries are too many, 2 are fine (control)
        byte[] raw1 = {0, 0x40, 0, (byte) 0x80}; // 2x2 1-bit: row0 = 0,1 ; row1 = 1,0
        rejects(build("IHDR", ihdr(2, 2, 1, 3, 0, 0, 0), "PLTE", new byte[9], "IDAT", z(raw1), "IEND", END), "too many");
        Png ok = PngDecoder.decode(build("IHDR", ihdr(2, 2, 1, 3, 0, 0, 0), "PLTE", PLTE2, "IDAT", z(raw1), "IEND", END));
        assertArrayEquals(new int[] {0, 1, 1, 0}, ok.samples());
    }

    @Test
    void paletteIndexOutOfRange() {
        byte[] raw = {0, 0, 2, 0, 1, 0}; // index 2 with a 2-entry palette
        rejects(build("IHDR", ihdr(2, 2, 8, 3, 0, 0, 0), "PLTE", PLTE2, "IDAT", z(raw), "IEND", END), "out of range");
    }

    @Test
    void unusedPaddingBitsInSubByteRowsAreIgnoredButSamplesCountCorrectly() {
        // 3 wide 1-bit palette: row bytes 0b1010_1111 -> samples 1,0,1 (padding bits 1111 ignored)
        byte[] raw = {0, (byte) 0xAF};
        Png p = PngDecoder.decode(build("IHDR", ihdr(3, 1, 1, 3, 0, 0, 0), "PLTE", PLTE2, "IDAT", z(raw), "IEND", END));
        assertArrayEquals(new int[] {1, 0, 1}, p.samples());
    }

    @Test
    void idatMustBeContiguousAndPresent() {
        byte[] zz = z(RAW);
        byte[] a = java.util.Arrays.copyOfRange(zz, 0, 3);
        byte[] b = java.util.Arrays.copyOfRange(zz, 3, zz.length);
        Png split = PngDecoder.decode(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", a, "IDAT", b, "IEND", END));
        assertArrayEquals(new int[] {1, 2, 3, 4}, split.samples()); // control: contiguous split is fine
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", a, "tEXt", new byte[] {'k', 0, 'v'}, "IDAT", b, "IEND", END), "non-contiguous");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IEND", END), "missing IDAT");
    }

    @Test
    void badFilterTypeByteNamesTheRow() {
        byte[] raw = {0, 1, 2, 7, 3, 4};
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(raw), "IEND", END), "filter type byte 7 in row 1");
        byte[] five = {0, 1, 2, 5, 3, 4}; // 5 is the first illegal value: the decoder's own check must name the row
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(five), "IEND", END), "filter type byte 5 in row 1");
        byte[] four = {0, 1, 2, 4, 3, 4}; // 4 (Paeth) is legal: control
        assertEquals(2, PngDecoder.decode(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(four), "IEND", END)).width());
    }

    @Test
    void inflatedSizeMustMatchExactly() {
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(new byte[] {0, 1, 2, 0, 3}), "IEND", END), "too short");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(new byte[] {0, 1, 2, 0, 3, 4, 9}), "IEND", END), "too long");
        byte[] zz = z(RAW);
        byte[] withJunk = java.util.Arrays.copyOf(zz, zz.length + 2);
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", withJunk, "IEND", END), "trailing");
        byte[] garbage = {1, 2, 3, 4, 5};
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", garbage, "IEND", END), "zlib");
    }

    @Test
    void endOfFileRules() {
        byte[] c = control();
        byte[] trailing = java.util.Arrays.copyOf(c, c.length + 1);
        rejects(trailing, "after IEND");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(RAW)), "truncated");
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "IDAT", z(RAW), "IEND", new byte[1]), "IEND must be empty");
    }

    @Test
    void ancillaryChunksAreSkippedButCriticalUnknownAreRejected() {
        Png p = PngDecoder.decode(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "tEXt", new byte[] {'a', 0, 'b'},
                "IDAT", z(RAW), "zzZz", new byte[2], "IEND", END));
        assertArrayEquals(new int[] {1, 2, 3, 4}, p.samples());
        rejects(build("IHDR", ihdr(2, 2, 8, 0, 0, 0, 0), "ABCD", new byte[0], "IDAT", z(RAW), "IEND", END), "unknown critical");
    }

    @Test
    void suggestedPaletteOnTruecolourIsIgnored() {
        byte[] raw = {0, 1, 2, 3, 4, 5, 6}; // 1x... 2x1 RGB
        Png p = PngDecoder.decode(build("IHDR", ihdr(2, 1, 8, 2, 0, 0, 0), "PLTE", PLTE2, "IDAT", z(raw), "IEND", END));
        assertNull(p.palette());
        assertArrayEquals(new int[] {1, 2, 3, 4, 5, 6}, p.samples());
    }

    @Test
    void flippingAnyByteGivesExceptionOrIdenticalImage() {
        Png src = PngRoundTripTest.random(new Random(5), 6, 5, 3, 4);
        byte[] good = PngEncoder.encode(src, FilterMode.ADAPTIVE);
        for (int i = 0; i < good.length; i++) {
            byte[] b = good.clone();
            b[i] ^= 0x10;
            try {
                assertEquals(src, PngDecoder.decode(b), "byte " + i);
            } catch (IllegalArgumentException expected) {
                // rejected: fine
            }
        }
    }

    @Test
    void everyTruncationIsRejected() {
        byte[] good = PngEncoder.encode(PngRoundTripTest.random(new Random(6), 5, 4, 6, 8), FilterMode.FIXED_4);
        for (int n = 0; n < good.length; n++) {
            final int len = n;
            assertThrows(IllegalArgumentException.class, () -> PngDecoder.decode(java.util.Arrays.copyOf(good, len)), "len " + len);
        }
        assertNotNull(PngDecoder.decode(good));
    }

    @Test
    void pngRecordValidatesItsInputs() {
        assertThrows(IllegalArgumentException.class, () -> new Png(2, 1, 0, 8, new int[] {1}, null));
        assertThrows(IllegalArgumentException.class, () -> new Png(1, 1, 0, 1, new int[] {2}, null));
        assertThrows(IllegalArgumentException.class, () -> new Png(1, 1, 3, 1, new int[] {0}, null));
        assertThrows(IllegalArgumentException.class, () -> new Png(1, 1, 3, 1, new int[] {0}, new int[3]));
        assertThrows(IllegalArgumentException.class, () -> new Png(1, 1, 0, 8, new int[] {0}, new int[1]));
        assertThrows(IllegalArgumentException.class, () -> new Png(1, 1, 2, 16, new int[] {0, 0, 0}, null));
        int[] s = {5};
        Png p = new Png(1, 1, 0, 8, s, null);
        s[0] = 9;
        assertEquals(5, p.samples()[0]); // defensive copy
    }
}

package ae.png;

import static org.junit.jupiter.api.Assertions.*;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Random;
import javax.imageio.ImageIO;
import org.junit.jupiter.api.Test;

class PngRoundTripTest {
    static Png random(Random rnd, int w, int h, int colorType, int depth) {
        int ch = Png.channels(colorType);
        int[] s = new int[w * h * ch];
        int max = (1 << depth) - 1;
        int[] pal = null;
        if (colorType == 3) {
            int n = 1 + rnd.nextInt(1 << depth);
            pal = new int[n];
            for (int i = 0; i < n; i++) pal[i] = rnd.nextInt(1 << 24);
            max = n - 1;
        }
        for (int i = 0; i < s.length; i++) s[i] = rnd.nextInt(max + 1);
        return new Png(w, h, colorType, depth, s, pal);
    }

    static final int[][] FORMATS = {
        {0, 1}, {0, 2}, {0, 4}, {0, 8}, {2, 8}, {3, 1}, {3, 2}, {3, 4}, {3, 8}, {4, 8}, {6, 8}
    };

    @Test
    void roundTripEveryFormatAndFilterMode() {
        Random rnd = new Random(42);
        for (int[] f : FORMATS) {
            for (FilterMode mode : FilterMode.values()) {
                for (int[] dim : new int[][] {{1, 1}, {3, 5}, {9, 2}, {17, 7}}) {
                    Png p = random(rnd, dim[0], dim[1], f[0], f[1]);
                    Png q = PngDecoder.decode(PngEncoder.encode(p, mode));
                    assertEquals(p, q, "type " + f[0] + " depth " + f[1] + " mode " + mode + " " + dim[0] + "x" + dim[1]);
                }
            }
        }
    }

    @Test
    void adaptiveNeverLargerRawScoreThanAnyFixedChoiceOnGradient() {
        // a horizontal gradient: Sub filtering gives constant residuals, so the adaptive pick must be type 1 on every row after row 0
        int w = 32, h = 6;
        int[] s = new int[w * h];
        for (int y = 0; y < h; y++) for (int x = 0; x < w; x++) s[y * w + x] = x * 3;
        Png p = new Png(w, h, 0, 8, s, null);
        byte[] raw = PngEncoder.filteredScanlines(p, FilterMode.ADAPTIVE);
        int stride = 1 + w;
        for (int y = 0; y < h; y++) {
            int type = raw[y * stride];
            // row 0: Sub (1) and Paeth (4) coincide; lowest wins ties. Later rows: Up gives all zeros after row 0? no: rows are identical -> Up residuals 0
            if (y == 0) assertEquals(1, type, "row 0");
            else assertEquals(2, type, "row " + y);
        }
    }

    @Test
    void adaptiveScoreTreatsBytesAsSigned() {
        // 1x2 gray, rows [10] then [255]. Row 1 residuals: None 255 (signed 1), Sub 255 (1), Up 245 (signed -11 -> 11),
        // Average 255-5=250 (6), Paeth predictor b=10 -> 245 (11). Signed scoring picks None(0); unsigned would pick Up(2).
        Png p = new Png(1, 2, 0, 8, new int[] {10, 255}, null);
        byte[] raw = PngEncoder.filteredScanlines(p, FilterMode.ADAPTIVE);
        assertEquals(0, raw[2]);
        assertEquals((byte) 255, raw[3]);
    }

    @Test
    void adaptiveTieGoesToLowestFilterType() {
        Png p = new Png(2, 1, 0, 8, new int[] {0, 0}, null); // all-zero row: every filter scores 0
        assertEquals(0, PngEncoder.filteredScanlines(p, FilterMode.ADAPTIVE)[0]);
    }

    @Test
    void fixedModesWriteThatFilterTypeOnEveryRow() {
        Png p = random(new Random(1), 5, 4, 2, 8);
        for (int t = 0; t <= 4; t++) {
            byte[] raw = PngEncoder.filteredScanlines(p, FilterMode.values()[t]);
            int stride = 1 + 15;
            for (int y = 0; y < 4; y++) assertEquals(t, raw[y * stride]);
        }
    }

    @Test
    void sampleLayoutIsRowMajorTopRowFirst() {
        // 2x2 gray 8-bit: top row 1,2 ; bottom row 3,4
        Png p = new Png(2, 2, 0, 8, new int[] {1, 2, 3, 4}, null);
        byte[] raw = PngEncoder.filteredScanlines(p, FilterMode.FIXED_0);
        assertArrayEquals(new byte[] {0, 1, 2, 0, 3, 4}, raw);
    }

    @Test
    void packsSubByteSamplesMsbFirstWithRowPadding() {
        // 3 wide, 1-bit gray: 1,0,1 -> 1010_0000 = 0xA0 ; row 2: 0,1,1 -> 0110_0000 = 0x60
        Png p = new Png(3, 2, 0, 1, new int[] {1, 0, 1, 0, 1, 1}, null);
        assertArrayEquals(new byte[] {0, (byte) 0xA0, 0, 0x60}, PngEncoder.filteredScanlines(p, FilterMode.FIXED_0));
        // 3 wide, 4-bit palette: 15,1,2 -> 0xF1 0x20
        Png q = new Png(3, 1, 3, 4, new int[] {15, 1, 2}, new int[16]);
        assertArrayEquals(new byte[] {0, (byte) 0xF1, 0x20}, PngEncoder.filteredScanlines(q, FilterMode.FIXED_0));
    }

    @Test
    void encodedBytesStartWithSignatureAndHaveChunkOrder() {
        Png p = random(new Random(3), 4, 4, 3, 2);
        byte[] b = PngEncoder.encode(p, FilterMode.ADAPTIVE);
        assertArrayEquals(new byte[] {(byte) 0x89, 'P', 'N', 'G', 13, 10, 26, 10}, java.util.Arrays.copyOf(b, 8));
        assertEquals("IHDR", new String(b, 12, 4, java.nio.charset.StandardCharsets.US_ASCII));
        // 8 signature + (4 len + 4 type + 13 data + 4 crc) = 33; next chunk: 4 length bytes then the type at offset 37
        assertEquals("PLTE", new String(b, 37, 4, java.nio.charset.StandardCharsets.US_ASCII));
        String tail = new String(b, b.length - 8, 4, java.nio.charset.StandardCharsets.US_ASCII);
        assertEquals("IEND", tail);
    }

    // ---- differential tests against javax.imageio ----

    private static BufferedImage imageIoRead(byte[] png) throws IOException {
        BufferedImage img = ImageIO.read(new ByteArrayInputStream(png));
        assertNotNull(img, "ImageIO could not decode our PNG");
        return img;
    }

    @Test
    void imageIoDecodesOurRgbaToIdenticalPixels() throws IOException {
        Png p = random(new Random(9), 11, 6, 6, 8);
        BufferedImage img = imageIoRead(PngEncoder.encode(p, FilterMode.ADAPTIVE));
        for (int y = 0; y < 6; y++)
            for (int x = 0; x < 11; x++) {
                int i = (y * 11 + x) * 4;
                int argb = (p.samples()[i + 3] << 24) | (p.samples()[i] << 16) | (p.samples()[i + 1] << 8) | p.samples()[i + 2];
                assertEquals(argb, img.getRGB(x, y), "pixel " + x + "," + y);
            }
    }

    @Test
    void imageIoDecodesOurRgbEveryFilterMode() throws IOException {
        Png p = random(new Random(10), 13, 9, 2, 8);
        for (FilterMode m : FilterMode.values()) {
            BufferedImage img = imageIoRead(PngEncoder.encode(p, m));
            for (int y = 0; y < 9; y++)
                for (int x = 0; x < 13; x++) {
                    int i = (y * 13 + x) * 3;
                    int rgb = 0xFF000000 | (p.samples()[i] << 16) | (p.samples()[i + 1] << 8) | p.samples()[i + 2];
                    assertEquals(rgb, img.getRGB(x, y), m + " pixel " + x + "," + y);
                }
        }
    }

    @Test
    void imageIoDecodesOurPalettePng() throws IOException {
        Random rnd = new Random(11);
        for (int depth : new int[] {1, 2, 4, 8}) {
            Png p = random(rnd, 10, 5, 3, depth);
            BufferedImage img = imageIoRead(PngEncoder.encode(p, FilterMode.FIXED_4));
            for (int y = 0; y < 5; y++)
                for (int x = 0; x < 10; x++)
                    assertEquals(0xFF000000 | p.palette()[p.samples()[y * 10 + x]], img.getRGB(x, y), "depth " + depth);
        }
    }

    @Test
    void ourDecoderReadsImageIoWrittenRgbAndRgba() throws IOException {
        Random rnd = new Random(12);
        for (int type : new int[] {BufferedImage.TYPE_INT_RGB, BufferedImage.TYPE_INT_ARGB}) {
            BufferedImage img = new BufferedImage(14, 8, type);
            int[][] expect = new int[8][14];
            for (int y = 0; y < 8; y++)
                for (int x = 0; x < 14; x++) {
                    int argb = rnd.nextInt();
                    if (type == BufferedImage.TYPE_INT_RGB) argb |= 0xFF000000;
                    img.setRGB(x, y, argb);
                    expect[y][x] = img.getRGB(x, y);
                }
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            assertTrue(ImageIO.write(img, "png", out));
            Png p = PngDecoder.decode(out.toByteArray());
            assertEquals(type == BufferedImage.TYPE_INT_RGB ? 2 : 6, p.colorType());
            int ch = Png.channels(p.colorType());
            for (int y = 0; y < 8; y++)
                for (int x = 0; x < 14; x++) {
                    int i = (y * 14 + x) * ch;
                    int a = ch == 4 ? p.samples()[i + 3] : 255;
                    int argb = (a << 24) | (p.samples()[i] << 16) | (p.samples()[i + 1] << 8) | p.samples()[i + 2];
                    assertEquals(expect[y][x], argb, "pixel " + x + "," + y);
                }
        }
    }

    @Test
    void ourDecoderReadsImageIoWrittenGrayAndBinary() throws IOException {
        Random rnd = new Random(13);
        BufferedImage gray = new BufferedImage(9, 7, BufferedImage.TYPE_BYTE_GRAY);
        int[] expect = new int[63];
        for (int y = 0; y < 7; y++)
            for (int x = 0; x < 9; x++) {
                int v = rnd.nextInt(256);
                gray.getRaster().setSample(x, y, 0, v);
                expect[y * 9 + x] = v;
            }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        ImageIO.write(gray, "png", out);
        Png p = PngDecoder.decode(out.toByteArray());
        assertEquals(0, p.colorType());
        assertArrayEquals(expect, p.samples());

        BufferedImage bin = new BufferedImage(9, 7, BufferedImage.TYPE_BYTE_BINARY);
        int[] bits = new int[63];
        for (int y = 0; y < 7; y++)
            for (int x = 0; x < 9; x++) {
                int v = rnd.nextInt(2);
                bin.getRaster().setSample(x, y, 0, v);
                bits[y * 9 + x] = v;
            }
        out.reset();
        ImageIO.write(bin, "png", out);
        Png q = PngDecoder.decode(out.toByteArray());
        assertEquals(1, q.bitDepth());
        assertArrayEquals(bits, q.samples()); // 1-bit samples (gray level or palette index, depending on what ImageIO chose)
        for (int y = 0; y < 7; y++)
            for (int x = 0; x < 9; x++) {
                int v = q.samples()[y * 9 + x];
                int rgb = q.colorType() == 3 ? q.palette()[v] : v * 0xFFFFFF; // gray 1-bit: 0 black, 1 white
                assertEquals(bin.getRGB(x, y) & 0xFFFFFF, rgb, "pixel " + x + "," + y);
            }
    }
}
